import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Scene placement
  const position = config.position || [-2.5, -1.1, 0];
  group.position.set(position[0], position[1], position[2]);

  group.userData.handlers = {};
  const timelines = [];

  // Geometry: tessellated plane for displacement
  const scale = config.scale || [3.5, 2.2, 1];
  const geometry = new THREE.PlaneGeometry(scale[0], scale[1], 64, 64);

  // Load textures via cached loaders
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/parallax-stack.png';
  const depthUrl = config.depthMapUrl || '/prism-mock/home/nodes/parallax-stack.depth.png';

  const colorMap = ctx.textureLoader.load(imageUrl);
  const displacementMap = ctx.textureLoader.load(depthUrl);

  // Machined-metal PBR material with displacement
  const material = new THREE.MeshStandardMaterial({
    map: colorMap,
    displacementMap: displacementMap,
    displacementScale: 0.08,
    metalness: 0.45,
    roughness: 0.65,
    clearcoat: 0.15,
    clearcoatRoughness: 0.8,
    color: 0xe8ecf2, // paper
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Apply cinematic primitives: parallax-scroll, depth-rotate
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((primitive) => {
      if (ctx.primitives && typeof ctx.primitives[primitive.name] === 'function') {
        ctx.primitives[primitive.name](group, primitive.params || {});
      }
    });
  }

  // Entrance animation: weighted-settle (power4.out, 0.9s, overshoot effect)
  const startY = group.position.y;
  gsap.set(group, { opacity: 0, y: startY + 0.4 });

  const entranceTl = gsap.timeline();
  entranceTl.to(group, {
    opacity: 1,
    y: startY,
    duration: 0.9,
    ease: 'power4.out',
  }, 0);
  timelines.push(entranceTl);

  // Hover interaction: rise-in effect (0.15 scene units, power3.out, 0.7s)
  group.userData.handlers.hover = (isEntering) => {
    gsap.killTweensOf(group, 'y');
    const hoverTl = gsap.timeline();
    hoverTl.to(group, {
      y: isEntering ? startY + 0.15 : startY,
      duration: 0.7,
      ease: 'power3.out',
    }, 0);
    timelines.push(hoverTl);
  };

  // Click interaction: emit hub-home.select
  group.userData.handlers.click = () => {
    group.dispatchEvent({ type: 'select' });
  };

  // Resource cleanup
  group.userData.cleanup = () => {
    timelines.forEach((timeline) => timeline.kill());
    geometry.dispose();
    material.dispose();
    colorMap.dispose();
    displacementMap.dispose();
  };

  return group;
}
